  }
  gkyl_dg_bin_op_mem *mem = gkyl_dg_bin_op_mem_new(CARR(a1)->size, CBAS(b)->num_basis);
  for (int f = 0; f < nf; ++f) {
    gkyl_dg_div_op(mem, CBAS(b), f, ARR(out), f, CARR(a1), f, CARR(a2));
