static bool
physical_parameters(double ms, double mr, double qs, double qr, double eps0, double hbar)
{
  return isfinite(ms) && ms > 0 && isfinite(mr) && mr > 0 && isfinite(qs) && qs != 0 &&
    isfinite(qr) && qr != 0 && isfinite(eps0) && eps0 > 0 && isfinite(hbar) && hbar >= 0;
}

int
gpython_coulomb_log(size_t n, const double *samples, double ms, double mr,
  double qs, double qr, double eps0, double hbar, double *out)
{
  if (!physical_parameters(ms, mr, qs, qr, eps0, hbar)) return 1;
  for (size_t i = 0; i < n; ++i) {
    const double *p = samples + 5*i;
    for (int j = 0; j < 5; ++j)
      if (!isfinite(p[j]) || (j < 4 ? p[j] <= 0 : p[j] < 0)) return 1;
    out[i] = gkyl_coulomb_log(p[0], p[1], ms, mr, p[2], p[3], qs, qr, p[4], eps0, hbar);
  }
  return 0;
}

