 * grid, or shape. Uses Gkeyll's stored-distribution normalization unchanged. */
gpython_array *gpython_mom_gyrokinetic(const gpython_basis *cbasis,
  const gpython_basis *pbasis, const double *lower, const double *upper, const int *cells,
