    enum gkyl_distribution_moments id;
  } moments[] = {
    {"M0", GKYL_F_MOMENT_M0}, {"M1", GKYL_F_MOMENT_M1}, {"M2", GKYL_F_MOMENT_M2},
    {"M2par", GKYL_F_MOMENT_M2PAR}, {"M2perp", GKYL_F_MOMENT_M2PERP},
    {"M3par", GKYL_F_MOMENT_M3PAR}, {"M3perp", GKYL_F_MOMENT_M3PERP},
    {"ThreeMoments", GKYL_F_MOMENT_M0M1M2},
    {"FourMoments", GKYL_F_MOMENT_M0M1M2PARM2PERP},
    {"HamiltonianMoments", GKYL_F_MOMENT_HAMILTONIAN}
  };
  size_t choice = 0;
  for (; choice < sizeof(moments)/sizeof(moments[0]); ++choice)
    if (strcmp(moment, moments[choice].name) == 0) break;
  if (choice == sizeof(moments)/sizeof(moments[0])) return NULL;
  enum gkyl_distribution_moments id = moments[choice].id;
  if ((vdim == 1 && (id == GKYL_F_MOMENT_M2PERP || id == GKYL_F_MOMENT_M3PERP)) ||
      (id == GKYL_F_MOMENT_HAMILTONIAN && !phi)) return NULL;
