  gpython_array *f = array_arg(fcap), *bmag = array_arg(bcap);
  gpython_array *phi = phicap == Py_None ? NULL : array_arg(phicap);
  if (!cb || !pb || !f || !bmag || (phicap != Py_None && !phi))
    return NULL;
