  }
  int ndim = gpython_basis_ndim(pb);
  if (PyArray_SIZE(lo) != ndim || PyArray_SIZE(up) != ndim ||
      PyArray_SIZE(cells) != ndim) {
    Py_DECREF(lo);
    Py_DECREF(up);
    Py_DECREF(cells);
    PyErr_SetString(PyExc_ValueError,
                    "gyrokinetic grid must match the phase-space dimension");
